<script lang="ts">
  import {rpc,defaults,type Appearance} from '../lib/api';import {notify} from '../lib/ui';import Icon from './Icon.svelte';
  let {settings,change}:{settings:Appearance;change:(s:Appearance)=>void}=$props();
  function set(key:keyof Appearance,value:string){change({...settings,[key]:value});}
</script>
<div class="appearance-app"><div class="eyebrow">MAKE IT YOURS</div><h2>A familiar place to work.</h2><p class="muted">Your appearance lives on this Windows PC.</p><h3>Theme</h3><div class="theme-options"><button class:chosen={settings.theme==='dark'} onclick={()=>change({...settings,theme:'dark',window:'#1b2837',taskbar:'#15202c'})}><span class="theme-preview dark-preview"></span>Dark</button><button class:chosen={settings.theme==='light'} onclick={()=>change({...settings,theme:'light',window:'#f5f7fa',taskbar:'#e8edf4'})}><span class="theme-preview light-preview"></span>Light</button></div><h3>Colors</h3><div class="color-grid">{#each [{key:'accent',label:'Accent'},{key:'background',label:'Desktop'},{key:'taskbar',label:'Taskbar'},{key:'window',label:'Windows'}] as option}<label><span>{option.label}</span><input type="color" value={settings[option.key as keyof Appearance]} oninput={e=>set(option.key as keyof Appearance,e.currentTarget.value)}/></label>{/each}</div><h3>Wallpaper</h3><div class="wallpaper-preview" style:background-color={settings.background} style:background-image={settings.wallpaper?`url("${settings.wallpaper}")`:'none'}><Icon name="image" size={28}/></div><div class="toolbar"><button onclick={async()=>{try{const image=await rpc('pick_wallpaper',{});if(image)set('wallpaper',image);}catch(e){notify(e);}}}><Icon name="image" size={16}/> Choose image…</button><button disabled={!settings.wallpaper} onclick={()=>set('wallpaper','')}>Remove</button><span class="spacer"></span><button onclick={()=>change({...defaults})}>Reset to Defaults</button></div></div>
